Capture(c,O+"Out_reference_composition_before.png");b.AppendLine("inspected=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_reference_composition_inspect.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Match Reference Camera Composition")]
