static void SetGameView(StringBuilder b){try{var a=typeof(Editor).Assembly;var sizesType=a.GetType("UnityEditor.GameViewSizes");var singleton=typeof(ScriptableSingleton<>).MakeGenericType(sizesType);var sizes=singleton.GetProperty("instance",BindingFlags.Public|BindingFlags.Static).GetValue(null);var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new object[]{0});var get=group.GetType().GetMethod("GetGameViewSize");int total=(int)group.GetType().GetMethod("GetBuiltinCount").Invoke(group,null)+(int)group.GetType().GetMethod("GetCustomCount").Invoke(group,null);int chosen=-1;for(int i=0;i<total;i++){var size=get.Invoke(group,new object[]{i});int width=(int)size.GetType().GetProperty("width").GetValue(size),height=(int)size.GetType().GetProperty("height").GetValue(size);if(width>0&&height>0&&Mathf.Abs((float)width/height-16f/9)<.001f){chosen=i;break;}}if(chosen<0){var sizeType=a.GetType("UnityEditor.GameViewSize");var enumType=a.GetType("UnityEditor.GameViewSizeType");var instance=Activator.CreateInstance(sizeType,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{Enum.ToObject(enumType,0),16,9,"Reference 16:9"},null);group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{instance});chosen=total;}var viewType=a.GetType("UnityEditor.GameView");var view=EditorWindow.GetWindow(viewType);viewType.GetProperty("selectedSizeIndex",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).SetValue(view,chosen);b.AppendLine("gameView16by9=True index="+chosen);}catch(Exception e){b.AppendLine("GameView setting: "+e.Message);}}
